/**
 * /pages/MedicineCatalogList.jsx
 * ---------------------------------------------------------------------------
 * Route con CẤP 3 của `/medicine` — path '' của `/medicine/catalog`.
 */

import React from 'react'
import { Card, Table, Tag, Button } from 'antd'

import { useRouter } from '@/router'
import { useI18n } from '@/lang'

// ---- dữ liệu mock ----------------------------------------------------------
const MOCK_GROUPS = [
  { id: 1, code: 'GRP001', name: 'Thuốc giảm đau - hạ sốt', count: 12 },
  { id: 2, code: 'GRP002', name: 'Kháng sinh', count: 8 },
  { id: 3, code: 'GRP003', name: 'Vitamin & khoáng chất', count: 15 },
]

const MedicineCatalogList = () => {
  const router = useRouter()
  const { t } = useI18n()

  const goDetail = (id) =>
    router.push({ name: 'medicine-catalog-group', params: { id } })

  const columns = [
    { title: t('STT'), width: 60, render: (_, __, i) => i + 1 },
    { title: t('Mã nhóm'), dataIndex: 'code', width: 120 },
    {
      title: t('Tên nhóm'),
      dataIndex: 'name',
      render: (v, row) => <a onClick={() => goDetail(row.id)}>{v}</a>,
    },
    {
      title: t('Số thuốc'),
      dataIndex: 'count',
      width: 110,
      align: 'right',
      render: (v) => <Tag color="blue">{v}</Tag>,
    },
    {
      title: t('Thao tác'),
      width: 110,
      render: (_, row) => (
        <Button type="link" size="small" onClick={() => goDetail(row.id)}>
          {t('Chi tiết')}
        </Button>
      ),
    },
  ]

  return (
    <Card size="small" title={t('Danh sách danh mục')}>
      <Table
        rowKey="id"
        size="small"
        columns={columns}
        dataSource={MOCK_GROUPS}
        pagination={false}
      />
    </Card>
  )
}

export default MedicineCatalogList
